  /**
   * allCartItems iterates over GET /v1/order/cart/{cartId}/item (List all the items of a cart).
   *
   * It lists the IDs with {@link OrderApi.listCartItems}, then gets each object with
   * {@link OrderApi.getCartItem}, only when the loop reaches it. An object deleted in the
   * meantime is skipped. Any other error is thrown and stops the loop.
   *
   * @param cartId - Cart ID
   * @param options - the options of this call: signal, timeout, headers
   * @returns each {@link models.OrderCartItem}, one at a time: loop with `for await`
   * @example
   * for await (const item of client.order.allCartItems(cartId)) console.log(item);
   */
  allCartItems(cartId: string, options?: RequestOptions): AsyncIterable<models.OrderCartItem> {
    return this._each(
      () => this.listCartItems(cartId, options),
      (listedId) => this.getCartItem(cartId, listedId, options),
    );
  }

